package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.UnresolvedForwardReference;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.std.ContainerDeserializerBase;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.introspect.BeanProperty;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.type.TypeFactory;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.Collection;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class CollectionDeserializer_createContextual_TriageGen0Test {

    private DeserializationContext ctxt;
    private BeanProperty property;
    private JavaType collectionType;
    private JavaType contentType;
    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        ctxt = mock(DeserializationContext.class);
        property = mock(BeanProperty.class);
        typeFactory = TypeFactory.defaultInstance();
        contentType = typeFactory.constructType(String.class);
        collectionType = typeFactory.constructCollectionType(java.util.List.class, String.class);

        // Default behavior for ctxt
        when(ctxt.getConfig()).thenReturn(new DeserializationConfig(null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null));
        // Mocking the config requirements for findFormatFeature/findDeserializer internally if needed
        // However, since we are testing the logic of the method, we mock the return values of the calls within it.
    }

    @Test
    public void testCreateContextual_NoInstantiator_NoValueDeser() throws Exception {
        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, null, null, null);

        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(new StdDeserializer<Object>(Object.class) {});

        CollectionDeserializer result = (CollectionDeserializer) deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        // Since valueDeser was null, it should have been resolved via ctxt.findContextualValueDeserializer
    }

    @Test
    public void testCreateContextual_WithInstantiator_DelegateSuccess() throws Exception {
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        JsonDeserializer<Object> delegateDeser = mock(JsonDeserializer.class);

        when(instantiator.canCreateUsingDelegate()).thenReturn(true);
        when(instantiator.getDelegateType(any())).thenReturn(contentType);

        // We need to spy the deserializer to mock findDeserializer
        CollectionDeserializer deserializer = spy(new CollectionDeserializer(collectionType, null, null, instantiator));
        doReturn(delegateDeser).when(deserializer).findDeserializer(any(), eq(contentType), any());

        when(ctxt.findContextualValueDeserializer(contentType, property)).thenReturn(new StdDeserializer<Object>(Object.class) {});

        CollectionDeserializer result = (CollectionDeserializer) deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        // Verify delegate logic was triggered
        verify(instantiator).getDelegateType(any());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateContextual_WithInstantiator_DelegateTypeNull() throws Exception {
        ValueInstantiator instantiator = mock(ValueInstantiator.class);
        when(instantiator.canCreateUsingDelegate()).thenReturn(true);
        when(instantiator.getDelegateType(any())).thenReturn(null);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, null, null, instantiator);
        deserializer.createContextual(ctxt, property);
    }

    @Test
    public void testCreateContextual_WithExistingValueDeser_HandleSecondaryContextualization() throws Exception {
        JsonDeserializer<Object> existingValueDeser = mock(JsonDeserializer.class);
        JsonDeserializer<Object> contextualizedValueDeser = mock(JsonDeserializer.class);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, existingValueDeser, null, null);

        when(ctxt.handleSecondaryContextualization(eq(existingValueDeser), eq(property), eq(contentType)))
                .thenReturn(contextualizedValueDeser);

        CollectionDeserializer result = (CollectionDeserializer) deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(ctxt).handleSecondaryContextualization(existingValueDeser, property, contentType);
    }

    @Test
    public void testCreateContextual_WithTypeDeserializer() throws Exception {
        JsonDeserializer<Object> valueDeser = new StdDeserializer<Object>(Object.class) {};
        TypeDeserializer typeDeserializer = mock(TypeDeserializer.class);
        TypeDeserializer contextualTypeDeserializer = mock(TypeDeserializer.class);

        CollectionDeserializer deserializer = new CollectionDeserializer(collectionType, valueDeser, typeDeserializer, null);

        when(ctxt.handleSecondaryContextualization(any(), any(), any())).thenReturn(valueDeser);
        when(typeDeserializer.forProperty(property)).thenReturn(contextualizedTypeDeserializer);

        CollectionDeserializer result = (CollectionDeserializer) deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(typeDeserializer).forProperty(property);
    }

    @Test
    public void testCreateContextual_FindConvertingContentDeserializer() throws Exception {
        JsonDeserializer<Object> valueDeser = mock(JsonDeserializer.class);
        JsonDeserializer<Object> convertedDeser = mock(JsonDeserializer.class);

        CollectionDeserializer deserializer = spy(new CollectionDeserializer(collectionType, valueDeser, null, null));

        // Mock findConvertingContentDeserializer which is a protected method or part of the logic
        // Since it's a method in the same class, we spy to control it
        doReturn(convertedDeser).when(deserializer).findConvertingContentDeserializer(any(), any(), any());
        when(ctxt.handleSecondaryContextualization(eq(convertedDeser), eq(property), eq(contentType)))
                .thenReturn(convertedDeser);

        CollectionDeserializer result = (CollectionDeserializer) deserializer.createContextual(ctxt, property);

        assertNotNull(result);
        verify(deserializer).findConvertingContentDeserializer(eq(ctxt), eq(property), eq(valueDeser));
    }
}
